source_change.after:
if negative {
        negate(&mut words);
        if sum[0] & ((1_u64 << 30) - 1) != 0 {
            let mut borrow = 1_u64;
            for word in &mut words {
                let (value, underflow) = word.overflowing_sub(borrow);
                *word = value;
                borrow = u64::from(underflow);
            }
        }
    }
    store(image, destination, &words);
